#!/usr/bin/env python3
"""Mini stories: English graded retellings, Persian line by line, and drills.

The English sentences are the retellings published in
github.com/nathanschaumann/graded-readers by Nathan Schaumann (CC BY 4.0).
The Persian under each sentence, the vocabulary notes, the grammar points and
all of the questions are written for this project.
"""

CREDIT = {
    "en": "English stories: graded retellings by Nathan Schaumann "
          "(graded-readers, CC BY 4.0). Persian, notes and questions: Fluentify.",
    "fa": "داستان‌های انگلیسی: بازنویسی ساده‌شده از نیتن شومان "
          "(graded-readers، مجوز CC BY 4.0). فارسی، توضیح‌ها و پرسش‌ها: فلوئنتیفای.",
    "url": "https://github.com/nathanschaumann/graded-readers",
}

LEVELS = [
    {"id": "VE", "name": {"en": "Very easy", "fa": "خیلی آسان"}, "words": "150–400"},
    {"id": "E", "name": {"en": "Easy", "fa": "آسان"}, "words": "400–700"},
    {"id": "M", "name": {"en": "Medium", "fa": "متوسط"}, "words": "700–1200"},
]


def L(en, fa):
    return {"en": en, "fa": fa}


def P(*rows):
    """Sentence pairs, in reading order.

    Call it either as P((en, fa), (en, fa)) or as P(en, fa) for a single line.
    """
    if len(rows) == 2 and all(isinstance(r, str) for r in rows):
        rows = [rows]
    return [L(en, fa) for en, fa in rows]


def C(title_en, title_fa, pairs):
    return {"title": L(title_en, title_fa), "pairs": pairs}


